};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_searchCorpList
 * @description search Corp List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpList = async function () {
    const sbmOptions = {
        id: "tx_searchCorpList",
        method: "post",
        action: "/submission/etnIsuList.do?method=searchETNIsu",
        ref: "dma_searchCorpListReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/submission/etnIsuList.do?method=searchETNIsu",
        ref: "dma_searchCorpListByBeginIndexReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name searchCorpList
 * @description search Corp List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpList = async function () {
    const corpName = $c.util.getComponent('ipt_companyName').getValue();
    if (corpName.indexOf("?") !== -1) {
        await $c.win.alert("?는 사용할 수 없습니다");
        return;
    } else {
        scwin.clearBtnImage();
        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "");
        (document.corpListForm || { elements: [] }).target = "iframe";
        (document.corpListForm || { elements: [] }).action = "/submission/etnIsuList.do?method=searchETNIsu";
        await scwin.tx_searchCorpList();
    }
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    const corpName = $c.util.getComponent('ipt_companyName').getValue();
    if (corpName.indexOf("?") !== -1) {
        await $c.win.alert("?는 사용할 수 없습니다");
        return;
    } else {
        (document.corpListForm || { elements: [] }).action = "/submission/etnIsuList.do?method=searchETNIsu";
        (document.corpListForm || { elements: [] }).target = "iframe";
        await scwin.tx_searchCorpListByBeginIndex();
    }
};

/**
 * @method
 * @name swapImage
 * @description swap Image 처리
 * @param {Object} obj 컴포넌트
 * @param {*} no no
 * @returns {void}
 * @hidden N
 */
scwin.swapImage = function (obj, no) {
    $c.util.getComponent('dma_searchCorpListReq').set('pageIndex', 1);
    scwin.clearBtnImage();
    const frm = (document.corpListForm || { elements: [] });
    obj.setSrc("/img/submission/corpfind/btn_initial" + no + "_on.gif");
    if (no === "01") {
        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "A");
    } else {
        if (no === "02") {
            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "B");
        } else {
            if (no === "03") {
                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "C");
            } else {
                if (no === "04") {
                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "D");
                } else {
                    if (no === "05") {
                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "E");
                    } else {
                        if (no === "06") {
                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "F");
                        } else {
                            if (no === "07") {
                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "G");
                            } else {
                                if (no === "08") {
                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "H");
                                } else {
                                    if (no === "09") {
                                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "I");
                                    } else {
                                        if (no === "10") {
                                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "J");
                                        } else {
                                            if (no === "11") {
                                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "K");
                                            } else {
                                                if (no === "12") {
                                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "L");
                                                } else {
                                                    if (no === "13") {
                                                        $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "M");
                                                    } else {
                                                        if (no === "14") {
                                                            $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "N");
                                                        } else {
                                                            if (no === "18") {
                                                                $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "AZ");
                                                            } else {
                                                                if (no === "17") {
                                                                    $c.util.getComponent('dma_searchCorpListReq').set('beginIndex', "ETC");
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
};

