/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} isurCd isurCd
 * @param {String} kisComCd kisComCd
 * @param {String} repIsuCd repIsuCd
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCorpInfo = async function (isurCd, kisComCd, repIsuCd, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + isurCd + "\n";
    str += "kisComCd : " + kisComCd + "\n";
    str += "repIsuCd : " + repIsuCd + "\n";
    str += "repIsuSrtCd : " + repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    const returnKey = '' + dma_pageContext.get("returnKey") + '';
    try {
        const code = (repIsuCd === null || repIsuCd === "") ? "-" : repIsuCd;
        const name = (comNm === null || comNm === "") ? "-" : comNm;
        const obj = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).Potential).Provider;
        const frameId = obj.ActiveFrame.FrameID;
        const frame = obj.Provider(frameId).ActiveFrame;
        frame.fn_setSelectedData((String(((dma_pageContext.get("formKey") ?? "")) === null ? '' : ((dma_pageContext.get("formKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("formKey") ?? "")) === null ? '' : ((dma_pageContext.get("formKey") ?? "")))), (String(((dma_pageContext.get("keyValue") ?? "")) === null ? '' : ((dma_pageContext.get("keyValue") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("keyValue") ?? "")) === null ? '' : ((dma_pageContext.get("keyValue") ?? "")))), decodeURIComponent((String(((dma_pageContext.get("returnKey") ?? "")) === null ? '' : ((dma_pageContext.get("returnKey") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("returnKey") ?? "")) === null ? '' : ((dma_pageContext.get("returnKey") ?? ""))))), code, name);
        frame.fn_setPopupDataValue('');
        frame.fn_setPopupDataValue(code);
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jldfil00060' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n" + str);
    }
};
